using System;
using System.Drawing;
using System.Windows.Forms;
partial class Usagi {
    Screen patrolScreen;
    bool monitorEntry;
    Rectangle PatrolArea(){if(patrolScreen==null)patrolScreen=Screen.FromPoint(new System.Drawing.Point((int)x+Width/2,(int)y+Height-15));foreach(var screen in Screen.AllScreens)if(screen.DeviceName==patrolScreen.DeviceName){patrolScreen=screen;return screen.WorkingArea;}patrolScreen=Screen.PrimaryScreen;var area=patrolScreen.WorkingArea;x=Math.Max(area.Left+64*scale-Width/2,Math.Min(area.Right-64*scale-Width/2,x));y=Math.Min(y,area.Bottom-Height+8);monitorEntry=false;return area;}
    double WrapMargin {get{return 90*scale;}}
    static double WrapCenter(double center,double left,double right,double margin){double start=left-margin,period=right-left+margin*2;if(center>right+margin||center<start)return start+((center-start)%period+period)%period;return center;}
    static Rectangle[] MonitorBounds(Screen[] screens,bool work){var result=new Rectangle[screens.Length];for(int i=0;i<screens.Length;i++)result[i]=work?screens[i].WorkingArea:screens[i].Bounds;return result;}
    int MonitorIndex(Screen[] screens){for(int i=0;i<screens.Length;i++)if(screens[i].DeviceName==patrolScreen.DeviceName)return i;return 0;}
    void EnterMonitor(Screen screen,bool portal){patrolScreen=screen;monitorEntry=portal;saveIn=Math.Min(saveIn,1);refreshRateCheck=0;}
    double WalkingFloor(){var screens=Screen.AllScreens;if(screens.Length<2)return PatrolArea().Bottom-Height+8;var bounds=MonitorBounds(screens,false);var work=MonitorBounds(screens,true);return MonitorLayout.Floor(bounds,work,MonitorIndex(screens),x+Width/2)-Height+8;}
    void WrapPatrol(Rectangle area){double center=x+Width/2;var screens=Screen.AllScreens;if(screens.Length>1){var bounds=MonitorBounds(screens,false);var work=MonitorBounds(screens,true);double mapped;bool portal;int next=MonitorLayout.CrossWalk(bounds,work,MonitorIndex(screens),direction,center,WrapMargin,out mapped,out portal);if(next>=0){EnterMonitor(screens[next],portal);x=mapped-Width/2;if(portal){y=work[next].Bottom-Height+8;tracks.Clear();hearts.Clear();speechTime=0;}return;}}
        if(center>=area.Left+WrapMargin&&center<=area.Right-WrapMargin)monitorEntry=false;
        double wrapped=WrapCenter(center,area.Left,area.Right,WrapMargin);if(Math.Abs(wrapped-center)<.001)return;x=wrapped-Width/2;tracks.Clear();hearts.Clear();speechTime=0;}
    void ClipToMonitors(Graphics g){var area=PatrolArea();var screens=Screen.AllScreens;using(var region=new Region()){region.MakeEmpty();if(throwActive&&screens.Length>1){foreach(var screen in screens)AddClip(region,screen.Bounds,0);}else{AddClip(region,area,8);if(screens.Length>1&&!monitorEntry){var bounds=MonitorBounds(screens,false);var work=MonitorBounds(screens,true);int current=MonitorIndex(screens);foreach(int direction in new[]{-1,1}){int next=MonitorLayout.WalkNeighbor(bounds,work,current,direction);if(next>=0&&MonitorLayout.Direct(bounds,work,current,next,direction))AddClip(region,work[next],8);}}}g.SetClip(region,System.Drawing.Drawing2D.CombineMode.Replace);}}
    void AddClip(Region region,Rectangle rect,int extra){region.Union(new RectangleF((float)(rect.Left-Math.Floor(x)),(float)(rect.Top-Math.Floor(y)),rect.Width,rect.Height+extra));}
    bool AtPatrolEdge(Rectangle area){double center=x+Width/2;return center<area.Left+80*scale||center>area.Right-80*scale;}
}

static class MonitorLayout {
    internal static int CrossFlight(Rectangle[] bounds,int current,double x,double y){var a=bounds[current];if(x<a.Left)return Passage(bounds,current,0,y);if(x>=a.Right)return Passage(bounds,current,1,y);if(y<a.Top)return Passage(bounds,current,2,x);if(y>=a.Bottom)return Passage(bounds,current,3,x);return -1;}
    internal static int Passage(Rectangle[] bounds,int current,int edge,double coordinate){int result=-1;double best=double.MaxValue;var a=bounds[current];for(int i=0;i<bounds.Length;i++){if(i==current||bounds[i]==a)continue;var b=bounds[i];bool horizontal=edge<2;double gap=edge==0?Math.Abs(a.Left-b.Right):edge==1?Math.Abs(a.Right-b.Left):edge==2?Math.Abs(a.Top-b.Bottom):Math.Abs(a.Bottom-b.Top);if(gap>8||coordinate<(horizontal?b.Top:b.Left)||coordinate>=(horizontal?b.Bottom:b.Right))continue;double score=Math.Abs(coordinate-(horizontal?(b.Top+b.Bottom)/2.0:(b.Left+b.Right)/2.0));if(score<best){best=score;result=i;}}return result;}
    internal static int WalkNeighbor(Rectangle[] bounds,Rectangle[] work,int current,int direction){int result=-1;double best=double.MaxValue;var a=bounds[current];for(int i=0;i<bounds.Length;i++){var b=bounds[i];if(i==current||b==a||direction*((b.Left+b.Right)-(a.Left+a.Right))<=0)continue;double gap=Math.Max(0,direction>0?b.Left-a.Right:a.Left-b.Right),vertical=Math.Max(0,Math.Max(a.Top,b.Top)-Math.Min(a.Bottom,b.Bottom));double score=gap+vertical*2+Math.Abs(work[current].Bottom-work[i].Bottom)*.35;if(score<best){best=score;result=i;}}
        if(result>=0)return result;for(int i=0;i<bounds.Length;i++){if(i==current||bounds[i]==a)continue;double score=direction*(bounds[i].Left+bounds[i].Right)*1000.0+Math.Abs(bounds[i].Top-a.Top);if(score<best){best=score;result=i;}}return result;}
    internal static bool Direct(Rectangle[] bounds,Rectangle[] work,int current,int next,int direction){var a=bounds[current];var b=bounds[next];return Math.Abs(direction>0?a.Right-b.Left:a.Left-b.Right)<=8&&Math.Max(a.Top,b.Top)<Math.Min(a.Bottom,b.Bottom)&&Math.Abs(work[current].Bottom-work[next].Bottom)<=96&&Math.Abs(direction>0?work[current].Right-a.Right:work[current].Left-a.Left)<=8&&Math.Abs(direction>0?work[next].Left-b.Left:work[next].Right-b.Right)<=8;}
    internal static int CrossWalk(Rectangle[] bounds,Rectangle[] work,int current,int direction,double center,double margin,out double mapped,out bool portal){mapped=center;portal=false;int next=WalkNeighbor(bounds,work,current,direction);if(next<0)return -1;bool direct=Direct(bounds,work,current,next,direction);double edge=direction>0?(direct?bounds[current].Right:work[current].Right+margin):(direct?bounds[current].Left:work[current].Left-margin);if(direction>0?center<=edge:center>=edge)return -1;portal=!direct;if(portal)mapped=(direction>0?work[next].Left-margin:work[next].Right+margin)+(center-edge);return next;}
    internal static double Floor(Rectangle[] bounds,Rectangle[] work,int current,double center){foreach(int direction in new[]{-1,1}){int next=WalkNeighbor(bounds,work,current,direction);if(next<0||!Direct(bounds,work,current,next,direction))continue;double edge=direction>0?bounds[current].Right:bounds[current].Left;if(Math.Abs(center-edge)>64)continue;double u=Math.Max(0,Math.Min(1,(direction*(center-edge)+64)/128));return work[current].Bottom+(work[next].Bottom-work[current].Bottom)*u;}return work[current].Bottom;}
}
